import{_ as e,o as d,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"CLI 用法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md","lastUpdated":1793898870000}'),i={name:"guide/cli.md"};function o(c,t,r,l,h,n){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="cli-用法" tabindex="-1">CLI 用法 <a class="header-anchor" href="#cli-用法" aria-label="Permalink to &quot;CLI 用法&quot;">​</a></h1><p>所有入口都走同一个可执行文件，用 flag 切换行为：</p><table tabindex="0"><thead><tr><th>Flag</th><th>说明</th></tr></thead><tbody><tr><td><code>-tui</code></td><td>启动终端 UI（默认若未指定其它模式）</td></tr><tr><td><code>-web</code></td><td>启动 Web UI（浏览器访问）</td></tr><tr><td><code>-e &quot;&lt;prompt&gt;&quot;</code></td><td>headless 模式：发送一条消息并跑完一轮</td></tr><tr><td><code>-s &lt;id&gt;</code></td><td>恢复指定会话并进入终端 UI（回放历史 + 继续）</td></tr><tr><td><code>--fork &lt;id&gt;</code></td><td>以某会话为蓝本派生新会话后进入</td></tr><tr><td><code>-view &lt;id&gt;</code></td><td>以只读浏览模式进入终端 UI</td></tr><tr><td><code>-replay &lt;id&gt;</code></td><td>非交互回放某会话的事件流（Trajectory 视图），打印后退出</td></tr><tr><td><code>-replay &lt;id&gt; -w</code></td><td>打印该会话的 Web 只读分享链接，不输出正文</td></tr><tr><td><code>-ls</code></td><td>列出全部会话（id / 时间 / 条数 / 标题）</td></tr><tr><td><code>-search &lt;关键词&gt;</code></td><td>在全部会话正文里检索，列出命中会话与上下文片段</td></tr><tr><td><code>-image &lt;路径&gt;</code></td><td>给 <code>-e</code> 的这条消息附一张图片，可重复</td></tr><tr><td><code>-archive &lt;天数&gt;</code></td><td>把早于 N 天的会话导出成按月分组的 Markdown 归档后退出</td></tr><tr><td><code>-archive-prune</code></td><td>归档后删除原会话文件（破坏性，需配合 <code>-archive</code>）</td></tr><tr><td><code>-model &lt;名字&gt;</code></td><td>本次运行使用指定主模型（来自 <code>llm.models</code>）</td></tr><tr><td><code>-aux &lt;名字&gt;</code></td><td>本次运行指定辅助模型（上下文摘要用）</td></tr><tr><td><code>-web-host &lt;host&gt;</code></td><td><code>-replay -w</code> 打印分享链接时使用的基地址</td></tr><tr><td><code>-tools</code></td><td>打印当前 shell / 已启用工具 / 技能清单</td></tr><tr><td><code>-v</code></td><td>打印版本与已加载插件</td></tr><tr><td><code>-c &lt;path&gt;</code></td><td>指定配置文件路径（默认程序目录下的 <code>config.json</code>）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">示例</p><p><code>./gsh -replay 20260101-120000-ab12 -w</code> 默认输出 <code>http://localhost:8934/#/share/20260101-120000-ab12</code>；把 Web UI 跑在对外域名上时用 <code>-web-host</code> 指定真实基地址，见<a href="./sessions.html">会话管理</a>。</p></div><h2 id="首次运行" tabindex="-1">首次运行 <a class="header-anchor" href="#首次运行" aria-label="Permalink to &quot;首次运行&quot;">​</a></h2><p>程序以<strong>可执行文件所在目录</strong>为锚点解析配置、数据、日志与技能目录，与当前工作目录无关。首次运行会在程序目录生成 <code>config.json</code> 并在启动时打印四个路径（程序目录 / 配置 / 数据 / 日志），填入 <code>api_key</code> 后即可使用。</p><h2 id="带图片执行" tabindex="-1">带图片执行 <a class="header-anchor" href="#带图片执行" aria-label="Permalink to &quot;带图片执行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;这张报错截图是什么问题&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./shot.png</span></span></code></pre></div><p><code>-image</code> 可重复，图片按本地路径在<strong>发送时</strong>读取并编码成 data URL，会话里只留路径不存 base64——历史文件不会因为几张图膨胀成几十 MB。单图上限 8MB；读不到（路径写错、文件被删）时不会让整轮失败，那一张会被跳过并在提示文本里留下说明。</p><p>只有 <code>-e</code> 支持 <code>-image</code>；交互模式用终端 UI 的 <code>/image</code> 命令（见<a href="./tui.html">终端 UI</a>），Web UI 用输入框左侧的附件按钮。</p><p>Web UI 的麦克风按钮是另一条路：语音转成文字<strong>填进输入框</strong>，由你删改后再自己发送，不会自动发出。识别准确率撑不起「语音直接进模型」——错一个路径或标识符就得重来一轮；落成可编辑文本后，错字只是改几个字符。浏览器不支持 Web Speech API 时按钮不出现。</p><h2 id="归档旧会话" tabindex="-1">归档旧会话 <a class="header-anchor" href="#归档旧会话" aria-label="Permalink to &quot;归档旧会话&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -archive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 30 天前的会话 → .gsh/session/archive/YYYY-MM.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -archive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -archive-prune</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 归档后删除原会话文件</span></span></code></pre></div><p>归档只做<strong>导出</strong>，不动原始会话：搜索、<code>-replay</code>、只读分享照样能用。想把磁盘腾出来是另一件事，要显式加 <code>-archive-prune</code>。按月归到同一个 Markdown 里，方便成批查阅。</p>`,14)])])}const k=e(i,[["render",o]]);export{g as __pageData,k as default};
